-- Product specifications, plus a catalogue enrichment crawled from cellphones.com.vn.
--
-- Specifications are the 'Thông số kỹ thuật' table a customer reads on the source PDP:
-- an ordered list of name/value pairs. They are stored as rows rather than JSON so the
-- ordering is explicit and a spec can be queried later, matching how product_images is
-- already modelled.
--
-- Nothing existing is overwritten. Five categories and twenty products are ADDED, so no
-- order that already references a product can be invalidated.

-- Qualify unaccent() inside the wrapper, schema and dictionary both. It resolved
-- through the caller's search_path, which the app happens to set (hikari.schema)
-- but psql and pg_dump do not, so `SELECT * FROM catalog.products` failed outside
-- the app. The extension lives in catalog, not public. The index needs no rebuild:
-- the body is equivalent, only its name resolution is fixed rather than ambient.
CREATE OR REPLACE FUNCTION immutable_unaccent(text)
    RETURNS text
    LANGUAGE sql
    IMMUTABLE PARALLEL SAFE STRICT
AS $$ SELECT catalog.unaccent('catalog.unaccent'::regdictionary, $1) $$;

CREATE TABLE product_specs (
    id            UUID PRIMARY KEY,
    product_id    UUID         NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    name          VARCHAR(100) NOT NULL,
    value         VARCHAR(500) NOT NULL,
    display_order INT          NOT NULL DEFAULT 0
);

CREATE INDEX ix_product_specs_product ON product_specs (product_id);

